  1→import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { ConfigService } from '@nestjs/config';
  4→import { Repository } from 'typeorm';
  5→import { Vault } from './entities/vault.entity';
  6→import { PinnedCid } from './entities/pinned-cid.entity';
  7→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  8→import { User } from '../auth/entities/user.entity';
  9→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
 10→import { VaultExportDto } from './dto/vault-export.dto';
 11→import { QuotaResponseDto } from './dto/quota.dto';
 12→import { VaultConfigResponseDto } from './dto/vault-config.dto';
 13→import { TeeKeyStateService } from '../tee/tee-key-state.service';
 14→import { TeeKeysDto } from '../tee/dto/tee-keys.dto';
 15→
 16→/**
 17→ * Storage quota limit: 500 MiB
 18→ */
 19→export const QUOTA_LIMIT_BYTES = 500 * 1024 * 1024; // 524,288,000 bytes
 20→
 21→@Injectable()
 22→export class VaultService {
 23→  constructor(
 24→    @InjectRepository(Vault)
 25→    private readonly vaultRepository: Repository<Vault>,
 26→    @InjectRepository(PinnedCid)
 27→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 28→    @InjectRepository(FolderIpns)
 29→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 30→    @InjectRepository(User)
 31→    private readonly userRepository: Repository<User>,
 32→    private readonly teeKeyStateService: TeeKeyStateService,
 33→    private readonly configService: ConfigService
 34→  ) {}
 35→
 36→  /**
 37→   * Get application configuration including recycle bin retention period.
 38→   */
 39→  getConfig(): VaultConfigResponseDto {
 40→    const raw = this.configService.get<string>('RECYCLE_BIN_RETENTION_DAYS');
 41→    let retentionDays = Number(raw);
 42→    if (!Number.isFinite(retentionDays) || retentionDays < 0) {
 43→      retentionDays = 30;
 44→    }
 45→    return {
 46→      recycleBinRetentionDays: retentionDays,
 47→    };
 48→  }
 49→
 50→  /**
 51→   * Initialize a new vault for a user
 52→   * Creates the vault with encrypted keys on first sign-in
 53→   *
 54→   * @throws ConflictException if vault already exists for user
 55→   */
 56→  async initializeVault(userId: string, dto: InitVaultDto): Promise<VaultResponseDto> {
 57→    // Check if vault already exists
 58→    const existingVault = await this.vaultRepository.findOne({
 59→      where: { ownerId: userId },
 60→    });
 61→
 62→    if (existingVault) {
 63→      throw new ConflictException('Vault already exists for this user');
 64→    }
 65→
 66→    // Decode hex strings to buffers
 67→    const vault = this.vaultRepository.create({
 68→      ownerId: userId,
 69→      ownerPublicKey: Buffer.from(dto.ownerPublicKey, 'hex'),
 70→      encryptedRootFolderKey: Buffer.from(dto.encryptedRootFolderKey, 'hex'),
 71→      encryptedRootIpnsPrivateKey: Buffer.from(dto.encryptedRootIpnsPrivateKey, 'hex'),
 72→      rootIpnsName: dto.rootIpnsName,
 73→      initializedAt: null,
 74→    });
 75→
 76→    const savedVault = await this.vaultRepository.save(vault);
 77→
 78→    // Create root folder IPNS entry for publish tracking
 79→    // This allows IPNS publishes to work without requiring TEE fields on every publish
 80→    const rootFolderIpns = this.folderIpnsRepository.create({
 81→      userId,
 82→      ipnsName: dto.rootIpnsName,
 83→      latestCid: null, // No content yet
 84→      sequenceNumber: '0',
 85→      encryptedIpnsPrivateKey: null, // TEE key added when TEE is implemented
 86→      keyEpoch: null,
 87→      isRoot: true,
 88→    });
 89→    await this.folderIpnsRepository.save(rootFolderIpns);
 90→
 91→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
 92→    return this.toVaultResponse(savedVault, teeKeys);
 93→  }
 94→
 95→  /**
 96→   * Get vault for a user
 97→   *
 98→   * @throws NotFoundException if vault does not exist
 99→   */
100→  async getVault(userId: string): Promise<VaultResponseDto> {
101→    const vault = await this.vaultRepository.findOne({
102→      where: { ownerId: userId },
103→    });
104→
105→    if (!vault) {
106→      throw new NotFoundException('Vault not found');
107→    }
108→
109→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
110→    return this.toVaultResponse(vault, teeKeys);
111→  }
112→
113→  /**
114→   * Check if vault exists for user (returns null if not)
115→   */
116→  async findVault(userId: string): Promise<VaultResponseDto | null> {
117→    const vault = await this.vaultRepository.findOne({
118→      where: { ownerId: userId },
119→    });
120→
121→    if (!vault) return null;
122→
123→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
124→    return this.toVaultResponse(vault, teeKeys);
125→  }
126→
127→  /**
128→   * Get current storage quota usage for a user
129→   */
130→  async getQuota(userId: string): Promise<QuotaResponseDto> {
131→    const result = await this.pinnedCidRepository
132→      .createQueryBuilder('pin')
133→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
134→      .where('pin.user_id = :userId', { userId })
135→      .getRawOne<{ total: string }>();
136→
137→    const usedBytes = parseInt(result?.total ?? '0', 10);
138→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
139→
140→    return {
141→      usedBytes,
142→      limitBytes: QUOTA_LIMIT_BYTES,
143→      remainingBytes,
144→    };
145→  }
146→
147→  /**
148→   * Check if user has sufficient quota for additional storage
149→   *
150→   * @returns true if (current usage + additionalBytes) <= quota limit
151→   */
152→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
153→    const quota = await this.getQuota(userId);
154→    return quota.usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
155→  }
156→
157→  /**
158→   * Record a pinned CID for quota tracking
159→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
160→   */
161→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
162→    await this.pinnedCidRepository
163→      .createQueryBuilder()
164→      .insert()
165→      .into(PinnedCid)
166→      .values({
167→        userId,
168→        cid,
169→        sizeBytes: sizeBytes.toString(),
170→      })
171→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
172→      .execute();
173→  }
174→
175→  /**
176→   * Remove a pinned CID record
177→   * Idempotent - no error if CID not found
178→   */
179→  async recordUnpin(userId: string, cid: string): Promise<void> {
180→    await this.pinnedCidRepository.delete({
181→      userId,
182→      cid,
183→    });
184→  }
185→
186→  /**
187→   * Mark vault as initialized (first file uploaded)
188→   */
189→  async markInitialized(userId: string): Promise<void> {
190→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
191→  }
192→
193→  /**
194→   * Get export data for independent recovery.
195→   * Returns the minimal set of fields needed to reconstruct the vault:
196→   * root IPNS name + encrypted root keys + derivation hints.
197→   */
198→  async getExportData(userId: string): Promise<VaultExportDto> {
199→    const vault = await this.vaultRepository.findOne({
200→      where: { ownerId: userId },
201→    });
202→
203→    if (!vault) {
204→      throw new NotFoundException('Vault not found');
205→    }
206→
207→    const user = await this.userRepository.findOne({
208→      where: { id: userId },
209→    });
210→
211→    return {
212→      format: 'cipherbox-vault-export',
213→      version: '1.0',
214→      exportedAt: new Date().toISOString(),
215→      rootIpnsName: vault.rootIpnsName,
216→      encryptedRootFolderKey: vault.encryptedRootFolderKey.toString('hex'),
217→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey.toString('hex'),
218→      derivationMethod: user ? 'web3auth' : null,
219→    };
220→  }
221→
222→  /**
223→   * Convert Vault entity to response DTO with hex-encoded fields
224→   */
225→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
226→    return {
227→      id: vault.id,
228→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
229→      encryptedRootFolderKey: vault.encryptedRootFolderKey.toString('hex'),
230→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey.toString('hex'),
231→      rootIpnsName: vault.rootIpnsName,
232→      createdAt: vault.createdAt,
233→      initializedAt: vault.initializedAt,
234→      teeKeys,
235→    };
236→  }
237→}
