  1→import { type KeyboardEvent, useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { bytesToHex } from '@cipherbox/crypto';
  4→import { AppShell } from '../components/layout';
  5→import { LinkedMethods } from '../components/auth/LinkedMethods';
  6→import { SecurityTab } from '../components/mfa/SecurityTab';
  7→import { VaultExport } from '../components/vault/VaultExport';
  8→import { useAuth } from '../hooks/useAuth';
  9→import { useAuthStore } from '../stores/auth.store';
 10→import { useMfaStore } from '../stores/mfa.store';
 11→
 12→type SettingsTabId = 'linked-methods' | 'security';
 13→
 14→const TAB_IDS: SettingsTabId[] = ['linked-methods', 'security'];
 15→
 16→function handleTabKeyDown(
 17→  e: KeyboardEvent,
 18→  activeTab: SettingsTabId,
 19→  setActiveTab: (id: SettingsTabId) => void
 20→) {
 21→  const idx = TAB_IDS.indexOf(activeTab);
 22→  let newIdx: number | null = null;
 23→  if (e.key === 'ArrowRight') newIdx = (idx + 1) % TAB_IDS.length;
 24→  else if (e.key === 'ArrowLeft') newIdx = (idx - 1 + TAB_IDS.length) % TAB_IDS.length;
 25→  else if (e.key === 'Home') newIdx = 0;
 26→  else if (e.key === 'End') newIdx = TAB_IDS.length - 1;
 27→  if (newIdx !== null) {
 28→    e.preventDefault();
 29→    setActiveTab(TAB_IDS[newIdx]);
 30→    document.getElementById(`tab-${TAB_IDS[newIdx]}`)?.focus();
 31→  }
 32→}
 33→
 34→/**
 35→ * Settings page wrapped in AppShell.
 36→ * Protected route - redirects to login if not authenticated.
 37→ *
 38→ * Tabs: Linked Methods | Security
 39→ * VaultExport shown below tabs (always visible).
 40→ */
 41→export function SettingsPage() {
 42→  const { isAuthenticated, isLoading } = useAuth();
 43→  const navigate = useNavigate();
 44→  const [activeTab, setActiveTab] = useState<SettingsTabId>('linked-methods');
 45→  const [copied, setCopied] = useState(false);
 46→  const copyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 47→  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
 48→
 49→  const publicKeyHex = vaultKeypair?.publicKey ? `0x${bytesToHex(vaultKeypair.publicKey)}` : null;
 50→
 51→  const handleCopyPublicKey = useCallback(() => {
 52→    if (!publicKeyHex) return;
 53→    navigator.clipboard.writeText(publicKeyHex).then(() => {
 54→      setCopied(true);
 55→      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
 56→      copyTimeoutRef.current = setTimeout(() => setCopied(false), 2000);
 57→    });
 58→  }, [publicKeyHex]);
 59→
 60→  // Clean up timeout on unmount
 61→  useEffect(() => {
 62→    return () => {
 63→      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
 64→    };
 65→  }, []);
 66→
 67→  // Redirect if not authenticated.
 68→  // Skip during MFA enrollment — enableMFA() makes long Devnet calls that can
 69→  // outlive the access token, causing a background 401 → refresh failure → logout.
 70→  // The enrollment wizard must remain mounted to complete.
 71→  const isEnrolling = useMfaStore((s) => s.isEnrolling);
 72→  useEffect(() => {
 73→    if (!isLoading && !isAuthenticated && !isEnrolling) {
 74→      navigate('/');
 75→    }
 76→  }, [isAuthenticated, isLoading, isEnrolling, navigate]);
 77→
 78→  // Show loading state while checking authentication
 79→  if (isLoading) {
 80→    return (
 81→      <AppShell>
 82→        <div className="loading">Loading...</div>
 83→      </AppShell>
 84→    );
 85→  }
 86→
 87→  // Don't render if not authenticated (redirect is in progress)
 88→  if (!isAuthenticated) {
 89→    return null;
 90→  }
 91→
 92→  return (
 93→    <AppShell>
 94→      <div className="settings-content">
 95→        <h2 className="settings-title">[SETTINGS]</h2>
 96→
 97→        <section className="settings-section" aria-labelledby="settings-account-heading">
 98→          <h3 id="settings-account-heading" className="settings-section-heading">
 99→            {'// account & security'}
100→          </h3>
101→          <p className="settings-section-description">
102→            manage your authentication methods and account security.
103→          </p>
104→
105→          {/* Tab navigation */}
106→          <div className="settings-tabs" role="tablist" aria-label="Settings sections">
107→            <button
108→              type="button"
109→              role="tab"
110→              id="tab-linked-methods"
111→              aria-selected={activeTab === 'linked-methods'}
112→              aria-controls="panel-linked-methods"
113→              tabIndex={activeTab === 'linked-methods' ? 0 : -1}
114→              className={`settings-tab ${activeTab === 'linked-methods' ? 'active' : ''}`}
115→              onClick={() => setActiveTab('linked-methods')}
116→              onKeyDown={(e) => handleTabKeyDown(e, activeTab, setActiveTab)}
117→            >
118→              LINKED METHODS
119→            </button>
120→            <button
121→              type="button"
122→              role="tab"
123→              id="tab-security"
124→              aria-selected={activeTab === 'security'}
125→              aria-controls="panel-security"
126→              tabIndex={activeTab === 'security' ? 0 : -1}
127→              className={`settings-tab ${activeTab === 'security' ? 'active' : ''}`}
128→              onClick={() => setActiveTab('security')}
129→              onKeyDown={(e) => handleTabKeyDown(e, activeTab, setActiveTab)}
130→            >
131→              SECURITY
132→            </button>
133→          </div>
134→
135→          {/* Tab panels */}
136→          <div
137→            role="tabpanel"
138→            id="panel-linked-methods"
139→            aria-labelledby="tab-linked-methods"
140→            hidden={activeTab !== 'linked-methods'}
141→          >
142→            {activeTab === 'linked-methods' && <LinkedMethods />}
143→          </div>
144→
145→          <div
146→            role="tabpanel"
147→            id="panel-security"
148→            aria-labelledby="tab-security"
149→            hidden={activeTab !== 'security'}
150→          >
151→            {activeTab === 'security' && <SecurityTab />}
152→          </div>
153→        </section>
154→
155→        <section className="settings-section" style={{ marginTop: 'var(--spacing-md)' }}>
156→          <VaultExport />
157→        </section>
158→
159→        {publicKeyHex && (
160→          <section className="settings-section" style={{ marginTop: 'var(--spacing-md)' }}>
161→            <h3 className="settings-section-heading">{'// your public key'}</h3>
162→            <p className="settings-section-description">
163→              {'// share this key with others to receive shared files'}
164→            </p>
165→            <div className="settings-pubkey-box">
166→              <code className="settings-pubkey-value">{publicKeyHex}</code>
167→            </div>
168→            <button type="button" className="settings-pubkey-copy" onClick={handleCopyPublicKey}>
169→              {copied ? '--copied' : '--copy'}
170→            </button>
171→          </section>
172→        )}
173→      </div>
174→    </AppShell>
175→  );
176→}
