 557→  // ---- File operations ----
 558→
 559→  /**
 560→   * Upload a file to a folder.
 561→   *
 562→   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
 563→   * adds a FilePointer to the parent folder's metadata, and publishes.
 564→   *
 565→   * @param folderIpnsName - IPNS name of the target folder
 566→   * @param data - Raw file content as Uint8Array
 567→   * @param fileName - Display name for the file
 568→   * @param mimeType - MIME type of the file
 569→   * @param onProgress - Optional upload progress callback
 570→   * @returns CID of the uploaded encrypted file
 571→   */
 572→  async uploadFile(
 573→    folderIpnsName: string,
 574→    data: Uint8Array,
 575→    fileName: string,
 576→    mimeType: string,
 577→    onProgress?: ProgressCallback
 578→  ): Promise<{ cid: string }> {
 579→    return this.withOperation('uploadFile', async () => {
 580→      const folder = this.folderTree.get(folderIpnsName);
 581→      if (!folder) throw new Error('Folder not loaded');
 582→
 583→      if (folder.children.some((child) => child.name === fileName)) {
 584→        throw new Error('An item with this name already exists');
 585→      }
 586→
 587→      const fileId = crypto.randomUUID();
 588→
 589→      // 1. Encrypt and upload file, create file metadata
 590→      const uploadResult = await sdkCore.uploadFile({
 591→        data,
 592→        fileId,
 593→        mimeType,
 594→        folderKey: folder.folderKey,
 595→        userPublicKey: this.config.vaultKeypair.publicKey,
 596→        ctx: this.ctx,
 597→        onProgress,
 598→        teeKeys: this.config.teeKeys,
 599→      });
 600→
 601→      try {
 602→        // 2. Add FilePointer to folder's children
 603→        const { updatedChildren } = sdkCore.addFilePointerToFolder({
 604→          children: folder.children,
 605→          fileId,
 606→          fileName,
 607→          fileMetaIpnsName: uploadResult.fileMetaIpnsName,
 608→          ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
 609→        });
 610→
 611→        // 3. Concurrent: file IPNS batch publish + folder metadata update
 612→        //    These two operations are independent -- no data dependency between them.
 613→        //    Using Promise.allSettled to handle partial failures gracefully.
 614→        const [batchResult, folderResult] = await Promise.allSettled([
 615→          sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord], this.ctx),
 616→          sdkCore.updateFolderMetadataAndPublish({
 617→            children: updatedChildren,
 618→            folderKey: folder.folderKey,
 619→            ipnsPrivateKey: folder.ipnsKeypair.privateKey,
 620→            ipnsName: folderIpnsName,
 621→            sequenceNumber: folder.sequenceNumber,
 622→            ctx: this.ctx,
 623→          }),
 624→        ]);
 625→
 626→        // Folder metadata update is critical -- must succeed for upload to be valid
 627→        if (folderResult.status === 'rejected') {
 628→          throw folderResult.reason;
 629→        }
 630→
 631→        // File IPNS batch publish failure is non-critical -- the FilePointer in
 632→        // folder metadata is valid, and the file IPNS record will be created
 633→        // on next publish attempt or TEE republish cycle
 634→        // Note: if folder update fails but batch publish succeeded, an orphaned IPNS
 635→        // record may exist. This is benign -- no FilePointer references it, and the
 636→        // IPNS name will be reused on the next successful upload attempt.
 637→        if (batchResult.status === 'rejected') {
 638→          const batchError =
 639→            batchResult.reason instanceof Error
 640→              ? batchResult.reason
 641→              : new Error(String(batchResult.reason));
 642→          console.warn(
 643→            '[SDK] File IPNS batch publish failed (non-critical, will retry on next publish):',
 644→            batchError
 645→          );
 646→          this.emitter.emit({
 647→            type: 'ipns:batchPublishFailed',
 648→            ipnsNames: [uploadResult.ipnsRecord.ipnsName],
 649→            error: batchError,
 650→          });
 651→        } else if (batchResult.value?.totalFailed > 0) {
 652→          // Server accepted the request but reported partial failure for some records
 653→          console.warn(
 654→            `[SDK] File IPNS batch publish partially failed: ${batchResult.value.totalFailed} of ${batchResult.value.totalFailed + batchResult.value.totalSucceeded} records failed`
 655→          );
 656→          this.emitter.emit({
 657→            type: 'ipns:batchPublishFailed',
 658→            ipnsNames: [uploadResult.ipnsRecord.ipnsName],
 659→            error: new Error(
 660→              `Batch publish partial failure: ${batchResult.value.totalFailed} record(s) failed`
 661→            ),
 662→          });
 663→        }
 664→
 665→        const { newSequenceNumber } = folderResult.value;
 666→
 667→        // 4. Update internal state
 668→        folder.children = updatedChildren;
 669→        folder.sequenceNumber = newSequenceNumber;
 670→        folder.lastLoadedAt = Date.now();
 671→        this.folderTree.set(folderIpnsName, folder);
 672→
 673→        // 5. Emit events
 674→        this.emitter.emit({
 675→          type: 'file:uploaded',
 676→          folderId: folderIpnsName,
 677→          fileName,
 678→          cid: uploadResult.cid,
 679→        });
 680→        this.emitter.emit({
 681→          type: 'folder:updated',
 682→          folderId: folderIpnsName,
 683→          ipnsName: folderIpnsName,
 684→          children: updatedChildren,
 685→          sequenceNumber: newSequenceNumber,
 686→        });
 687→
 688→        // 6. Re-wrap file key for share recipients (best-effort)
 689→        try {
 690→          if (this.config.shareCallbacks) {
 691→            await this.reWrapNewItems(folderIpnsName, [
 692→              { keyType: 'file', itemId: fileId, plaintextKey: uploadResult.fileKey },
 693→            ]);
 694→          }
 695→        } catch (err) {
 696→          console.warn('[SDK] Post-upload re-wrapping failed:', err);
 697→        }
 698→
 699→        return { cid: uploadResult.cid };
 700→      } finally {
 701→        clearBytes(uploadResult.fileKey);
 702→      }
 703→    });
 704→  }
