 706→  /**
 707→   * Download a file using its per-file IPNS metadata.
 708→   *
 709→   * Resolves the file's IPNS record, decrypts the metadata with the
 710→   * folder key, then downloads and decrypts the file content.
 711→   * This is the primary download path for v2 folder metadata.
 712→   *
 713→   * @param fileMetaIpnsName - IPNS name of the file's metadata record
 714→   * @param folderKey - Parent folder's decrypted AES-256 key
 715→   * @param onProgress - Optional download progress callback
 716→   * @returns Decrypted file content
 717→   */
 718→  async downloadFromIpns(
 719→    fileMetaIpnsName: string,
 720→    folderKey: Uint8Array,
 721→    onProgress?: DownloadProgressCallback
 722→  ): Promise<Uint8Array> {
 723→    return this.withOperation('downloadFromIpns', async () => {
 724→      // 1. Resolve per-file IPNS to get FileMetadata
 725→      const resolved = await sdkCore.resolveFileMetadata(fileMetaIpnsName, folderKey, this.ctx);
 726→
 727→      // 2. Download and decrypt file content
 728→      const plaintext = await sdkCore.downloadAndDecrypt({
 729→        cid: resolved.metadata.cid,
 730→        fileKeyEncrypted: resolved.metadata.fileKeyEncrypted,
 731→        fileIv: resolved.metadata.fileIv,
 732→        userPrivateKey: this.config.vaultKeypair.privateKey,
 733→        encryptionMode: resolved.metadata.encryptionMode,
 734→        ctx: this.ctx,
 735→        onProgress,
 736→      });
 737→
 738→      this.emitter.emit({ type: 'file:downloaded', cid: resolved.metadata.cid });
 739→      return plaintext;
 740→    });
 741→  }
 742→
 743→  /**
 744→   * Download and decrypt a file from IPFS.
 745→   *
 746→   * Fetches the encrypted file content, unwraps the file key using the
 747→   * user's private key, and decrypts the content.
 748→   *
 749→   * @param cid - IPFS CID of the encrypted file content
 750→   * @param fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
 751→   * @param fileIv - Hex-encoded IV used for encryption
 752→   * @param encryptionMode - 'GCM' (default) or 'CTR'
 753→   * @param onProgress - Optional download progress callback
 754→   * @returns Decrypted file content
 755→   */
 756→  async downloadFile(
 757→    cid: string,
 758→    fileKeyEncrypted: string,
 759→    fileIv: string,
 760→    encryptionMode?: 'GCM' | 'CTR',
 761→    onProgress?: DownloadProgressCallback
 762→  ): Promise<Uint8Array> {
 763→    return this.withOperation('downloadFile', async () => {
 764→      const plaintext = await sdkCore.downloadAndDecrypt({
 765→        cid,
 766→        fileKeyEncrypted,
 767→        fileIv,
 768→        userPrivateKey: this.config.vaultKeypair.privateKey,
 769→        encryptionMode,
 770→        ctx: this.ctx,
 771→        onProgress,
 772→      });
 773→
 774→      this.emitter.emit({ type: 'file:downloaded', cid });
 775→
 776→      return plaintext;
 777→    });
 778→  }
