 996→  // ---- Operation wrapper ----
 997→
 998→  /**
 999→   * Wrap an async operation with event emission and error handling.
1000→   *
1001→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
1002→   * and 'error' on failure. Also calls the config callbacks if provided.
1003→   */
1004→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
1005→    const start = Date.now();
1006→    this.notifySafely(() => this.config.onOperationStart?.(name));
1007→    this.emitter.emit({ type: 'operation:start', operation: name });
1008→
1009→    try {
1010→      const result = await fn();
1011→      const durationMs = Date.now() - start;
1012→      this.notifySafely(() => this.config.onOperationEnd?.(name));
1013→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
1014→      return result;
1015→    } catch (error) {
1016→      this.notifySafely(() => this.config.onError?.(error as Error));
1017→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
1018→      throw error;
1019→    }
1020→  }
1021→
1022→  private notifySafely(fn: () => void): void {
1023→    try {
1024→      fn();
1025→    } catch (err) {
1026→      console.warn('[SDK] Lifecycle callback threw:', err);
1027→    }
1028→  }
1029→}
