13→/**
14→ * Callbacks for share-aware key re-wrapping.
15→ *
16→ * The SDK uses these to discover active shares and store re-wrapped keys
17→ * without taking a direct dependency on the shares API or stores.
18→ */
19→export type ShareCallbacks = {
20→  /** Find active shares covering a folder (including ancestor shares). */
21→  getCoveringShares: (folderIpnsName: string) => Promise<SentShareInfo[]>;
22→  /** Store re-wrapped keys for a share via the API. */
23→  addShareKeys: (
24→    shareId: string,
25→    keys: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>
26→  ) => Promise<void>;
27→};
