29→/**
30→ * Configuration for initializing a CipherBoxClient instance.
31→ *
32→ * Consumers provide authentication, keypair, and root folder details.
33→ * The SDK manages everything else internally.
34→ */
35→export type CipherBoxClientConfig = {
36→  /** Base URL for the CipherBox API (e.g., "https://api.cipherbox.cc") */
37→  apiUrl: string;
38→  /** Returns a valid access token. Consumer owns refresh logic. */
39→  getAccessToken: () => Promise<string>;
40→  /** User's vault keypair (secp256k1). Used for ECIES operations. */
41→  vaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
42→  /** Root folder IPNS name (k51.../bafzaa...) */
43→  rootIpnsName: string;
44→  /** Root folder key (AES-256, decrypted on login) */
45→  rootFolderKey: Uint8Array;
46→  /** TEE keys for IPNS key wrapping */
47→  teeKeys?: TeeKeys;
48→  /**
49→   * Callbacks for share-aware operations (re-wrapping).
50→   *
51→   * When provided, the SDK will automatically re-wrap file and folder keys
52→   * for share recipients after uploadFile() and createFolder(). This ensures
53→   * recipients can decrypt items added to shared folders after the share
54→   * was created.
55→   *
56→   * If not provided, re-wrapping is skipped (consumer must handle it).
57→   */
58→  shareCallbacks?: ShareCallbacks;
59→  /** Callback when an operation starts */
60→  onOperationStart?: (operation: string) => void;
61→  /** Callback when an operation completes */
62→  onOperationEnd?: (operation: string) => void;
63→  /** Callback when an error occurs */
64→  onError?: (error: Error) => void;
65→  /** Extra headers sent with every request (e.g., throttle bypass for testing). */
66→  defaultHeaders?: Record<string, string>;
67→  /**
68→   * Pre-built axios instance to use for all API calls.
69→   * When provided, the client uses this instead of creating its own instance.
70→   * Use this to share a single instance with the orval singleton (web app)
71→   * or to inject a fully-configured instance with 401 refresh logic.
72→   */
73→  axiosInstance?: AxiosInstance;
74→};
75→
76→/**
77→ * Internal state for a loaded folder.
78→ *
79→ * Tracks everything needed to read and update a folder's metadata.
80→ * This is SDK-internal state -- consumers receive simplified events.
81→ */
82→export type FolderState = {
83→  /** IPNS name identifying this folder */
84→  ipnsName: string;
85→  /** Decrypted AES-256 folder key */
86→  folderKey: Uint8Array;
87→  /** Ed25519 IPNS keypair for signing updates */
88→  ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
89→  /** Current IPNS sequence number (monotonically increasing) */
90→  sequenceNumber: bigint;
91→  /** Current folder children (files and subfolders) */
92→  children: FolderChild[];
93→  /** Full decrypted folder metadata, or null if not yet loaded */
94→  metadata: FolderMetadata | null;
95→  /** Timestamp (ms) of last successful load from IPNS */
96→  lastLoadedAt: number;
97→};
