    await sdkCore.registerCid(this.ctx, uploadResult.cid, uploadResult.fileSize ?? 0);
  } else {
    // PSA: pin by CID (data already on IPFS via CipherBox upload)
    await (this.externalProvider as any).pinByCid(uploadResult.cid);
    await sdkCore.registerCid(this.ctx, uploadResult.cid, uploadResult.fileSize ?? 0);
  }
  // In external-only mode, unpin from CipherBox after external pin confirms
  sdkCore.unpinFromIpfs(this.ctx, uploadResult.cid).catch(() => {});
}

if (mode === 'dual' && this.externalProvider) {
  // Best-effort mirror to external provider
  try {
    const ext = this.config.pinningConfig!.externalProvider!;
    if (ext.protocol === 'kubo') {
      await this.externalProvider.pin(encryptedData);
    } else {
      await (this.externalProvider as any).pinByCid(uploadResult.cid);
    }
  } catch (err) {
    // Non-blocking warning
    const providerName = this.config.pinningConfig?.externalProvider?.providerName ?? 'external node';
    this.emitter.emit({
      type: 'pin:secondaryFailed',
      cid: uploadResult.cid,
      providerName,
      error: err instanceof Error ? err.message : String(err),
    } as SdkEvent);
  }
}
```

