BullMQ processor with `@Processor('pin-migration')`:

```typescript
@Processor('pin-migration')
export class MigrationProcessor extends WorkerHost {
  constructor(
    @InjectRepository(PinMigration) private readonly migrationRepo: Repository<PinMigration>,
    @InjectRepository(PinnedCid) private readonly pinnedCidRepo: Repository<PinnedCid>,
    private readonly migrationService: MigrationService,
    private readonly configService: ConfigService
  ) { super(); }

  async process(job: Job<{ migrationId: string }>): Promise<void> {
    const migration = await this.migrationRepo.findOneOrFail({ where: { id: job.data.migrationId } });

    // Get all CIDs for user
    const pinnedCids = await this.pinnedCidRepo.find({ where: { userId: migration.userId } });

    const TEE_URL = this.configService.get<string>('TEE_WORKER_URL');
    const TEE_SECRET = this.configService.get<string>('TEE_AUTH_SECRET');
    const BATCH_SIZE = 10;

    for (let i = 0; i < pinnedCids.length; i += BATCH_SIZE) {
      // Check if paused or cancelled
      const current = await this.migrationRepo.findOneOrFail({ where: { id: migration.id } });
      if (current.status === 'paused' || current.status === 'cancelled') break;

      const batch = pinnedCids.slice(i, i + BATCH_SIZE);
      const cids = batch.map(p => p.cid);

      try {
        const response = await fetch(`${TEE_URL}/migrate`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${TEE_SECRET}`,
          },
          body: JSON.stringify({
            cids,
            sourceConfigEncrypted: migration.sourceConfigEncrypted,
            destConfigEncrypted: migration.destConfigEncrypted,
          }),
        });

        if (!response.ok) {
          const text = await response.text();
          // Handle 401 specifically (token expired)
          if (response.status === 401) {
            await this.migrationService.updateProgress(migration.id, 0, cids.length, cids);
            await this.migrationRepo.update(migration.id, { status: 'paused' });
            return; // Stop processing -- user needs to update credentials
          }
          throw new Error(`TEE migration failed: ${response.status} ${text}`);
        }

        const result = await response.json();
        await this.migrationService.updateProgress(
          migration.id,
          result.succeeded?.length ?? 0,
          result.failed?.length ?? 0,
          result.failed
        );
      } catch (err) {
        await this.migrationService.updateProgress(migration.id, 0, cids.length, cids);
      }
    }

    // Mark complete
    const final = await this.migrationRepo.findOneOrFail({ where: { id: migration.id } });
    if (final.status === 'running') {
      await this.migrationRepo.update(migration.id, {
        status: 'completed',
        completedAt: new Date(),
      });
    }
  }
}
```

