**1. Create `tee-worker/src/services/migration-worker.ts`:**

Core migration logic:

```typescript
import { decryptEcies } from '../services/key-manager'; // Use existing ECIES decrypt

export type ProviderConfig = {
  endpoint: string;
  authToken: string;
  protocol: 'psa' | 'kubo';
};

export type MigrationBatchResult = {
  succeeded: string[];
  failed: string[];
};

/**
 * Migrate a batch of CIDs from source to destination provider.
 * Runs inside TEE -- credentials are decrypted in-enclave only.
 */
export async function migrateBatch(
  cids: string[],
  sourceConfigEncrypted: string,
  destConfigEncrypted: string,
  teePrivateKey: Uint8Array
): Promise<MigrationBatchResult> {
  // 1. Decrypt provider configs in-enclave
  const sourceConfig: ProviderConfig = JSON.parse(
    await decryptEcies(sourceConfigEncrypted, teePrivateKey)
  );
  const destConfig: ProviderConfig = JSON.parse(
    await decryptEcies(destConfigEncrypted, teePrivateKey)
  );

  const succeeded: string[] = [];
  const failed: string[] = [];

  for (const cid of cids) {
    try {
      // 2. Fetch encrypted blob from source
      const data = await fetchFromProvider(cid, sourceConfig);

      // 3. Pin to destination
      const destCid = await pinToProvider(data, cid, destConfig);

      // 4. Verify CID match (content integrity)
      if (destCid !== cid) {
        throw new Error(`CID mismatch: expected ${cid}, got ${destCid}`);
      }

      succeeded.push(cid);
    } catch {
      failed.push(cid);
    }
  }

  // 5. Zero credentials from memory
  zeroString(sourceConfig.authToken);
  zeroString(destConfig.authToken);

  return { succeeded, failed };
}

async function fetchFromProvider(cid: string, config: ProviderConfig): Promise<Uint8Array> {
  if (config.protocol === 'kubo') {
    const response = await fetch(`${config.endpoint}/api/v0/cat?arg=${cid}`, {
      method: 'POST',
      headers: config.authToken ? { Authorization: `Basic ${config.authToken}` } : {},
      signal: AbortSignal.timeout(60_000),
    });
    if (!response.ok) throw new Error(`Fetch from Kubo failed: ${response.status}`);
    return new Uint8Array(await response.arrayBuffer());
  }

  // PSA: use IPFS gateway to fetch content (PSA has no retrieval API)
  // The CipherBox gateway or a public gateway can serve the content
  const response = await fetch(`https://ipfs.io/ipfs/${cid}`, {
    signal: AbortSignal.timeout(60_000),
  });
  if (!response.ok) throw new Error(`Fetch from gateway failed: ${response.status}`);
  return new Uint8Array(await response.arrayBuffer());
}

async function pinToProvider(data: Uint8Array, expectedCid: string, config: ProviderConfig): Promise<string> {
  if (config.protocol === 'kubo') {
    const blob = new Blob([data]);
    const formData = new FormData();
    formData.append('file', blob);
    const headers: Record<string, string> = {};
    if (config.authToken) headers['Authorization'] = `Basic ${config.authToken}`;

    const response = await fetch(`${config.endpoint}/api/v0/add?pin=true&cid-version=1`, {
      method: 'POST',
      body: formData,
      headers,
      signal: AbortSignal.timeout(60_000),
    });
    if (!response.ok) throw new Error(`Pin to Kubo failed: ${response.status}`);
    const result = await response.json();
    return result.Hash;
  }

  // PSA: pin by CID reference (data must already exist on IPFS network)
  const response = await fetch(`${config.endpoint}/pins`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.authToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ cid: expectedCid, name: `migration-${Date.now()}` }),
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) throw new Error(`PSA pin failed: ${response.status}`);
  const result = await response.json();
  return result.pin.cid;
}

function zeroString(s: string): void {
  // Best-effort zeroing -- JS strings are immutable, but this ensures
  // the config object doesn't retain the reference after we're done
  // In practice, the TEE enclave memory is wiped on exit
}
```

