import { migrateBatch } from '../services/migration-worker';
import { getTeePrivateKey } from '../services/key-manager'; // or wherever TEE key is loaded

export async function handleMigrate(req, res) {
  const { cids, sourceConfigEncrypted, destConfigEncrypted } = req.body;

  if (!cids || !Array.isArray(cids) || !sourceConfigEncrypted || !destConfigEncrypted) {
    return res.status(400).json({ error: 'Missing required fields: cids, sourceConfigEncrypted, destConfigEncrypted' });
  }

  try {
    const teePrivateKey = getTeePrivateKey();
    const result = await migrateBatch(cids, sourceConfigEncrypted, destConfigEncrypted, teePrivateKey);
    return res.status(200).json(result);
  } catch (err) {
    return res.status(500).json({ error: err instanceof Error ? err.message : 'Migration failed' });
  }
}
