    const client = getApiClient();
    const response = await client.post('/migration/start', { sourceConfigEncrypted, destConfigEncrypted });
    return response.data;
  },

  async getStatus(): Promise<MigrationStatus | null> {
    const client = getApiClient();
    try {
      const response = await client.get('/migration/status');
      return response.data;
    } catch {
      return null; // No migration exists
    }
  },

  async pause(migrationId: string): Promise<void> {
    const client = getApiClient();
    await client.post(`/migration/${migrationId}/pause`);
  },

  async resume(migrationId: string): Promise<void> {
    const client = getApiClient();
    await client.post(`/migration/${migrationId}/resume`);
  },

  async cancel(migrationId: string): Promise<void> {
    const client = getApiClient();
    await client.post(`/migration/${migrationId}/cancel`);
  },
};
